_whitespace_re = re.compile(r"\s+")
_control_chars_re = re.compile(r"[\x00-\x08\x0b-\x0c\x0e-\x1f\x7f]")
_word_re = re.compile(r"\b\w+\b", re.UNICODE)
_meta_description_re = re.compile(r"^description$", re.IGNORECASE)
_link_protocols_re = re.compile(r"^(mailto|javascript|tel|data|file):", re.IGNORECASE)

_BLOCKED_IP_RANGES = [
    ipaddress.ip_network("127.0.0.0/8"),
    ipaddress.ip_network("10.0.0.0/8"),
    ipaddress.ip_network("172.16.0.0/12"),
    ipaddress.ip_network("192.168.0.0/16"),
    ipaddress.ip_network("169.254.0.0/16"),
    ipaddress.ip_network("::1/128"),
    ipaddress.ip_network("fc00::/7"),
    ipaddress.ip_network("fe80::/10"),
]

def _now_ms() -> int:
    return int(time.monotonic() * 1000)

def _normalize_text(text: str) -> str:
    text = unicodedata.normalize("NFKC", text)
    text = _control_chars_re.sub("", text)
    text = text.strip()
    text = _whitespace_re.sub(" ", text)
    return text

def _hash_url(url: str) -> str:
    return hashlib.sha256(url.encode("utf-8")).hexdigest()

def _safe_url(url: str) -> str:
    url = url.strip()
    url = _control_chars_re.sub("", url)
    return url

def _is_http_url(url: str) -> bool:
    try:
        parsed = urlparse(url)
        return parsed.scheme in ("http", "https") and bool(parsed.netloc)
    except ValueError:
        return False

def _is_ssrf_safe(url: str) -> bool:
    try:
        parsed = urlparse(url)
        if not parsed.netloc:
            return False
        host = parsed.hostname
        if not host:
            return False
        try:
            ip = ipaddress.ip_address(host)
            for blocked_range in _BLOCKED_IP_RANGES:
                if ip in blocked_range:
                    return False
        except ValueError:
            pass
        return True
    except Exception:
        return False

def _canonicalize_url(url: str) -> str:
    url = _safe_url(url)
    url, _ = urldefrag(url)
    parsed = urlparse(url)
    scheme = (parsed.scheme or "https").lower()
    netloc = parsed.netloc.lower()
    if "@" in netloc:
        netloc = netloc.split("@", 1)[1]
    if ":" in netloc:
        host, port_str = netloc.rsplit(":", 1)
        try:
            port = int(port_str)
            if (scheme == "http" and port == 80) or (scheme == "https" and port == 443):
                netloc = host
        except ValueError:
            pass
    path = parsed.path or "/"
    if path != "/" and path.endswith("/"):
        path = path[:-1]
    query_params = parse_qs(parsed.query, keep_blank_values=True)
    tracking_params = {"utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "fbclid", "gclid"}
    filtered_params = {k: v for k, v in query_params.items() if k not in tracking_params}
    sorted_params = sorted(filtered_params.items())
    query = urlencode(sorted_params, doseq=True) if sorted_params else ""
    rebuilt = urlunparse((scheme, netloc, path, "", query, ""))
    return rebuilt

def _tokenize(text: str) -> List[str]:
    text = text.lower()
    tokens = _word_re.findall(text)
    return tokens

