    __slots__ = ("allow_all", "allow_prefixes", "disallow_prefixes", "crawl_delay_s", "fetched_at")
    def __init__(self, allow_all: bool, allow_prefixes: List[str], disallow_prefixes: List[str], crawl_delay_s: Optional[float], fetched_at: float):
