        self._ttl_seconds = ttl_seconds
    async def get(self, client: httpx.AsyncClient, base_url: str, user_agent: str, timeout_s: float) -> RobotsRules:
        host = urlparse(base_url).netloc.lower()
        if host in self._cache:
            rules = self._cache[host]
            if time.time() - rules.fetched_at < self._ttl_seconds:
                return rules
        async with self._lock:
            if host in self._cache:
                rules = self._cache[host]
                if time.time() - rules.fetched_at < self._ttl_seconds:
                    return rules
            rules = await self._fetch_rules(client, base_url, user_agent, timeout_s)
            self._cache[host] = rules
            return rules
    async def _fetch_rules(self, client: httpx.AsyncClient, base_url: str, user_agent: str, timeout_s: float) -> RobotsRules:
        robots_url = urljoin(base_url, "/robots.txt")
        fetched_at = time.time()
        try:
            response = await client.get(robots_url, headers={"User-Agent": user_agent, "Accept": "text/plain"}, timeout=timeout_s, follow_redirects=True)
            if response.status_code >= 400:
                return RobotsRules(False, [], ["/"], None, fetched_at)
            text = response.text or ""
        except httpx.TimeoutException:
            return RobotsRules(False, [], ["/"], None, fetched_at)
        except httpx.RequestError:
            return RobotsRules(False, [], ["/"], None, fetched_at)
        user_agent_lower = user_agent.lower()
        lines = [line.strip() for line in text.splitlines()]
        groups: List[Tuple[Set[str], List[str], List[str], Optional[float]]] = []
        current_uas: Set[str] = set()
        current_allow: List[str] = []
        current_disallow: List[str] = []
        current_delay: Optional[float] = None
        def flush_group() -> None:
            nonlocal current_uas, current_allow, current_disallow, current_delay
            if current_uas:
                groups.append((set(current_uas), list(current_allow), list(current_disallow), current_delay))
            current_uas = set()
            current_allow = []
            current_disallow = []
            current_delay = None
        for raw_line in lines:
            if not raw_line or raw_line.startswith("#"):
                continue
            if "#" in raw_line:
                raw_line = raw_line.split("#", 1)[0].strip()
            if not raw_line:
                continue
            if ":" not in raw_line:
                continue
            key, value = raw_line.split(":", 1)
            key = key.strip().lower()
            value = value.strip()
            if key == "user-agent":
                if current_uas and (current_allow or current_disallow or current_delay is not None):
                    flush_group()
                current_uas.add(value.lower())
            elif key == "allow":
                current_allow.append(value)
            elif key == "disallow":
                current_disallow.append(value)
            elif key == "crawl-delay":
                try:
                    current_delay = max(0.0, float(value))
                except ValueError:
                    pass
        flush_group()
        matched: List[Tuple[int, List[str], List[str], Optional[float]]] = []
        for user_agents, allows, disallows, delay in groups:
            if "*" in user_agents:
                matched.append((1, allows, disallows, delay))
            for entry in user_agents:
                if entry and entry != "*":
                    if user_agent_lower.startswith(entry) or entry.startswith(user_agent_lower):
                        matched.append((2, allows, disallows, delay))
        if not matched:
            return RobotsRules(True, [], [], None, fetched_at)
        matched.sort(key=lambda item: item[0], reverse=True)
        best = matched[0]
        if not best[1] and not best[2]:
            return RobotsRules(True, [], [], best[3], fetched_at)
        return RobotsRules(False, best[1], best[2], best[3], fetched_at)
class HostRateLimiter:
    def __init__(self, default_delay_ms: int) -> None:
        self._default_delay_ms = default_delay_ms
        self._next_allowed_ms: Dict[str, int] = {}
        self._locks: Dict[str, asyncio.Lock] = {}
        self._locks_lock = asyncio.Lock()
    async def _get_lock(self, host: str) -> asyncio.Lock:
        async with self._locks_lock:
            if host not in self._locks:
                self._locks[host] = asyncio.Lock()
            return self._locks[host]
    async def wait(self, host: str, delay_ms: Optional[int]) -> None:
        delay = self._default_delay_ms if delay_ms is None else max(100, int(delay_ms))
        jitter = int(delay * 0.1 * (hash(host) % 100) / 100.0)
        delay = delay + jitter
        lock = await self._get_lock(host)
        async with lock:
            now = _now_ms()
            wait_until = self._next_allowed_ms.get(host, now)
            if wait_until < now:
                wait_until = now
            self._next_allowed_ms[host] = wait_until + delay
            sleep_time = (wait_until - now) / 1000.0
            if sleep_time > 0:
                await asyncio.sleep(sleep_time)
class Crawler:
    def __init__(self, index: "VectorIndex") -> None:
        self._index = index
        self._robots = RobotsCache()
    async def crawl(self, seed_urls: List[str], depth: int, max_pages: int, same_domain_only: bool, timeout_s: float, concurrency: int, user_agent: str, obey_robots_txt: bool, per_host_delay_ms: int, max_text_chars: int, max_response_bytes: int, log_queue: Optional["asyncio.Queue[Dict[str, Any]]"] = None) -> Dict[str, Any]:
        canonical_seeds = []
        for url_str in seed_urls:
            if not _is_http_url(str(url_str)):
                continue
            canonical = _canonicalize_url(str(url_str))
            if not _is_ssrf_safe(canonical):
                continue
            canonical_seeds.append(canonical)
        if not canonical_seeds:
            raise ValueError("No valid seed URLs provided")
        allowed_hosts: Optional[Set[str]] = None
        if same_domain_only:
            allowed_hosts = {urlparse(url).netloc.lower() for url in canonical_seeds}
        visited: Set[str] = set()
        queued: Set[str] = set()
        queue: asyncio.Queue[Tuple[str, int]] = asyncio.Queue(maxsize=max_pages * 2)
        for url in canonical_seeds:
            if url not in queued:
                queued.add(url)
                try:
                    queue.put_nowait((url, 0))
                except asyncio.QueueFull:
                    break
        limiter = HostRateLimiter(per_host_delay_ms)
        async def emit(event: Dict[str, Any]) -> None:
            if log_queue is not None:
                try:
                    await asyncio.wait_for(log_queue.put(event), timeout=0.1)
                except (asyncio.TimeoutError, asyncio.QueueFull):
                    pass
        limits = httpx.Limits(max_keepalive_connections=concurrency, max_connections=concurrency * 2)
        timeout_config = httpx.Timeout(connect=timeout_s / 2, read=timeout_s, write=timeout_s, pool=timeout_s)
        async with httpx.AsyncClient(http2=True, headers={"User-Agent": user_agent}, limits=limits, timeout=timeout_config, follow_redirects=False) as client:
            semaphore = asyncio.Semaphore(concurrency)
            indexed_count = 0
            fetched_count = 0
            errored_count = 0
            robots_blocked_count = 0
            started_ms = _now_ms()
            async def worker() -> None:
                nonlocal indexed_count, fetched_count, errored_count, robots_blocked_count
                while True:
                    try:
                        url, current_depth = await asyncio.wait_for(queue.get(), timeout=2.0)
                    except asyncio.TimeoutError:
                        break
                    try:
                        if len(visited) >= max_pages:
                            continue
                        if url in visited:
                            continue
                        host = urlparse(url).netloc.lower()
                        if allowed_hosts is not None and host not in allowed_hosts:
                            continue
                        async with semaphore:
                            visited.add(url)
                            await emit({"type": "visit", "url": url, "depth": current_depth, "ts": _now_ms()})
                            rules_delay_ms: Optional[int] = None
                            if obey_robots_txt:
                                base = f"{urlparse(url).scheme}://{host}"
                                rules = await self._robots.get(client, base, user_agent, timeout_s)
                                path = urlparse(url).path or "/"
                                if not rules.allowed(path):
                                    robots_blocked_count += 1
                                    await emit({"type": "skip_robots", "url": url, "depth": current_depth, "ts": _now_ms()})
                                    continue
                                if rules.crawl_delay_s is not None:
                                    rules_delay_ms = int(max(0.0, rules.crawl_delay_s) * 1000)
                            await limiter.wait(host, rules_delay_ms)
                            redirect_count = 0
                            current_url = url
                            final_response = None
                            while redirect_count < 5:
                                try:
                                    response = await client.get(current_url, headers={"User-Agent": user_agent, "Accept": "text/html,application/xhtml+xml;q=0.9,*/*;q=0.8"})
                                except httpx.RequestError as req_err:
                                    errored_count += 1
                                    await emit({"type": "request_error", "url": current_url, "error": type(req_err).__name__, "ts": _now_ms()})
                                    break
                                if response.status_code in (301, 302, 303, 307, 308):
                                    location = response.headers.get("Location")
                                    if not location:
                                        break
                                    redirect_url = urljoin(current_url, location)
                                    redirect_url = _canonicalize_url(redirect_url)
                                    if not _is_ssrf_safe(redirect_url):
                                        errored_count += 1
                                        await emit({"type": "ssrf_blocked", "url": redirect_url, "ts": _now_ms()})
                                        break
                                    redirect_host = urlparse(redirect_url).netloc.lower()
                                    if allowed_hosts is not None and redirect_host not in allowed_hosts:
                                        errored_count += 1
                                        await emit({"type": "domain_blocked", "url": redirect_url, "ts": _now_ms()})
                                        break
                                    current_url = redirect_url
                                    redirect_count += 1
                                else:
                                    final_response = response
                                    break
                            if final_response is None:
                                continue
                            fetched_count += 1
                            content_type = (final_response.headers.get("content-type") or "").lower()
                            if final_response.status_code >= 400:
                                errored_count += 1
                                await emit({"type": "http_error", "url": current_url, "status": final_response.status_code, "ts": _now_ms()})
                                continue
                            if "text/html" not in content_type and "application/xhtml+xml" not in content_type:
                                await emit({"type": "skip_non_html", "url": current_url, "content_type": content_type, "ts": _now_ms()})
                                continue
                            content_length = int(final_response.headers.get("content-length", 0))
                            if content_length > max_response_bytes:
                                errored_count += 1
                                await emit({"type": "response_too_large", "url": current_url, "size": content_length, "ts": _now_ms()})
                                continue
                            try:
                                html = final_response.text[:max_response_bytes]
                            except Exception:
                                errored_count += 1
                                await emit({"type": "decode_error", "url": current_url, "ts": _now_ms()})
                                continue
                            document, links = self._extract(current_url, html, max_text_chars)
                            if document is not None:
                                added = await self._index.add_document(document)
                                if added:
                                    indexed_count += 1
                                    await emit({"type": "indexed", "url": current_url, "title": document.title, "ts": _now_ms()})
                                else:
                                    await emit({"type": "dedup", "url": current_url, "ts": _now_ms()})
                            if current_depth < depth and links:
                                for link in links:
                                    if len(visited) >= max_pages:
                                        break
                                    if link in visited or link in queued:
                                        continue
                                    link_host = urlparse(link).netloc.lower()
                                    if allowed_hosts is not None and link_host not in allowed_hosts:
                                        continue
                                    queued.add(link)
                                    try:
                                        queue.put_nowait((link, current_depth + 1))
                                    except asyncio.QueueFull:
                                        break
                    except Exception:
                        errored_count += 1
                    finally:
                        queue.task_done()
            workers = [asyncio.create_task(worker()) for _ in range(concurrency)]
            await asyncio.gather(*workers, return_exceptions=True)
            duration_ms = _now_ms() - started_ms
            await emit({"type": "done", "indexed": indexed_count, "visited": len(visited), "fetched": fetched_count, "errors": errored_count, "robots_blocked": robots_blocked_count, "duration_ms": duration_ms, "ts": _now_ms()})
            return {"indexed": indexed_count, "visited": len(visited), "fetched": fetched_count, "errors": errored_count, "robots_blocked": robots_blocked_count, "duration_ms": duration_ms}
    def _extract(self, url: str, html: str, max_text_chars: int) -> Tuple[Optional[Document], List[str]]:
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            return None, []
        for tag in soup(["script", "style", "noscript", "template", "svg", "canvas", "iframe", "object", "embed", "head"]):
            tag.decompose()
        title = ""
        if soup.title:
            title = _normalize_text(soup.title.get_text(strip=True))
        if not title:
            h1_tag = soup.find("h1")
            if h1_tag:
                title = _normalize_text(h1_tag.get_text(strip=True))
        meta_description = ""
        meta_tag = soup.find("meta", attrs={"name": _meta_description_re})
        if meta_tag and hasattr(meta_tag, "get"):
            content_attr = meta_tag.get("content")
            if content_attr:
                meta_description = _normalize_text(str(content_attr))
        main_content = soup.find("main") or soup.find("article") or (soup.body if soup.body else soup)
        text = _normalize_text(main_content.get_text(" ", strip=True))
        if not text:
            return None, self._extract_links(url, soup)
        if len(text) > max_text_chars:
            sentences = text.split(". ")
            truncated = []
            current_len = 0
            for sentence in sentences:
                if current_len + len(sentence) + 2 > max_text_chars:
                    break
                truncated.append(sentence)
                current_len += len(sentence) + 2
            text = ". ".join(truncated)
            if text and not text.endswith("."):
                text += "."
        snippet = text[:500] if len(text) > 500 else text
        doc_id = _hash_url(_canonicalize_url(url))
        document = Document(doc_id=doc_id, url=_canonicalize_url(url), title=title or url, text=text, snippet=snippet, meta_description=meta_description, fetched_at_ms=_now_ms())
        links = self._extract_links(url, soup)
        return document, links
    def _extract_links(self, base_url: str, soup: BeautifulSoup) -> List[str]:
        seen_links: Set[str] = set()
        unique_links: List[str] = []
        for anchor in soup.find_all("a", limit=1000):
            if not hasattr(anchor, "get"):
                continue
            href = anchor.get("href")
            if not href:
                continue
            href = href.strip()
            if href.startswith("#"):
                continue
            if _link_protocols_re.match(href):
                continue
            try:
                absolute_url = urljoin(base_url, href)
            except Exception:
                continue
            if not _is_http_url(absolute_url):
                continue
            canonical = _canonicalize_url(absolute_url)
            if not _is_ssrf_safe(canonical):
                continue
            if canonical not in seen_links:
                seen_links.add(canonical)
                unique_links.append(canonical)
            if len(unique_links) >= 500:
                break
        return unique_links
class VectorIndex:
    def __init__(self, model_name: str = "sentence-transformers/all-MiniLM-L6-v2") -> None:
        self._model_name = model_name
        self._model: Optional[Any] = None
        self._model_lock = asyncio.Lock()
        self._docs: List[Document] = []
        self._doc_ids: Set[str] = set()
        self._url_to_idx: Dict[str, int] = {}
        self._emb_list: List[np.ndarray] = []
        self._norm_emb_list: List[np.ndarray] = []
        self._kw_df: Dict[str, int] = {}
        self._kw_doc_tf: List[Dict[str, int]] = []
        self._lock = asyncio.Lock()
    async def _ensure_model(self) -> None:
        if self._model is not None:
            return
        async with self._model_lock:
            if self._model is not None:
                return
            if SentenceTransformer is None:
                raise RuntimeError("sentence-transformers library is not available")
            loop = asyncio.get_running_loop()
            self._model = await loop.run_in_executor(None, lambda: SentenceTransformer(self._model_name))
    async def add_document(self, doc: Document) -> bool:
        async with self._lock:
            if doc.doc_id in self._doc_ids:
                return False
            if doc.url in self._url_to_idx:
                return False
        await self._ensure_model()
        input_text = doc.title + "\n" + doc.text
        if len(input_text) > 8000:
            input_text = input_text[:8000]
        try:
            embedding = await self._embed_text(input_text)
        except Exception:
            return False
        embedding = embedding.astype(np.float32, copy=False)
        if not np.isfinite(embedding).all():
            return False
        norm = np.linalg.norm(embedding) + 1e-12
        normalized_embedding = (embedding / norm).astype(np.float32, copy=False)
        tf = self._compute_tf(doc)
        async with self._lock:
            if doc.doc_id in self._doc_ids:
                return False
            self._docs.append(doc)
            self._doc_ids.add(doc.doc_id)
            self._url_to_idx[doc.url] = len(self._docs) - 1
            self._emb_list.append(embedding)
            self._norm_emb_list.append(normalized_embedding)
            self._kw_doc_tf.append(tf)
            for term in tf.keys():
                self._kw_df[term] = self._kw_df.get(term, 0) + 1
        return True
    def _compute_tf(self, doc: Document) -> Dict[str, int]:
        tokens = _tokenize(doc.title + " " + doc.text)
        tf: Dict[str, int] = {}
        for token in tokens:
            tf[token] = tf.get(token, 0) + 1
        return tf
    async def _embed_text(self, text: str) -> np.ndarray:
        await self._ensure_model()
        if self._model is None:
            raise RuntimeError("Model not initialized")
        model = self._model
        loop = asyncio.get_running_loop()
        vector = await loop.run_in_executor(None, lambda: np.asarray(model.encode([text], normalize_embeddings=False, show_progress_bar=False))[0])
        return vector
    async def search(self, query: str, top_k: int, mode: SearchMode) -> Dict[str, Any]:
        normalized_query = _normalize_text(query)
        if not normalized_query:
            raise ValueError("Empty query")
        async with self._lock:
            num_docs = len(self._docs)
            docs_snapshot = list(self._docs)
            kw_df = dict(self._kw_df)
            kw_doc_tf = list(self._kw_doc_tf)
            norm_emb_array = np.vstack(self._norm_emb_list) if self._norm_emb_list else None
        if num_docs == 0:
            return {"results": [], "count": 0, "indexed": 0}
        neural_scores: Optional[np.ndarray] = None
        if mode in (SearchMode.NEURAL, SearchMode.HYBRID):
            await self._ensure_model()
            query_vector = await self._embed_text(normalized_query)
            query_vector = query_vector.astype(np.float32, copy=False)
            if not np.isfinite(query_vector).all():
                query_vector = np.zeros_like(query_vector)
            query_norm_val = np.linalg.norm(query_vector) + 1e-12
            query_norm = (query_vector / query_norm_val).astype(np.float32, copy=False)
            if norm_emb_array is not None and norm_emb_array.shape[1] == query_norm.shape[0]:
                neural_scores = np.matmul(norm_emb_array, query_norm.reshape(-1, 1)).reshape(-1)
        keyword_scores = None
        if mode in (SearchMode.KEYWORD, SearchMode.HYBRID):
            keyword_scores = self._keyword_scores(normalized_query, docs_snapshot, kw_df, kw_doc_tf)
        results: List[Dict[str, Any]] = []
        for i, doc in enumerate(docs_snapshot):
            ns = float(neural_scores[i]) if neural_scores is not None and i < len(neural_scores) else None
            ks = float(keyword_scores[i]) if keyword_scores is not None and i < len(keyword_scores) else None
            if mode == SearchMode.NEURAL:
                score = ns if ns is not None else 0.0
            elif mode == SearchMode.KEYWORD:
                score = ks if ks is not None else 0.0
            else:
                alpha = 0.7
                beta = 0.3
                score = (alpha * (ns if ns is not None else 0.0)) + (beta * (ks if ks is not None else 0.0))
            results.append({"rank": 0, "score": float(score), "neural_score": ns, "keyword_score": ks, "url": doc.url, "title": doc.title, "snippet": doc.snippet, "meta_description": doc.meta_description, "fetched_at_ms": doc.fetched_at_ms})
        results.sort(key=lambda item: item["score"], reverse=True)
        results = results[:max(1, top_k)]
        for idx, result in enumerate(results, start=1):
            result["rank"] = idx
        return {"results": results, "count": len(results), "indexed": num_docs}
    def _keyword_scores(self, query: str, docs: List[Document], df: Dict[str, int], doc_tf: List[Dict[str, int]]) -> np.ndarray:
        query_terms = _tokenize(query)
        if not query_terms:
            return np.zeros((len(docs),), dtype=np.float32)
        N = max(1, len(docs))
        idf: Dict[str, float] = {}
        for term in set(query_terms):
            df_val = df.get(term, 0)
            idf[term] = float(np.log((N + 1) / (df_val + 1)) + 1.0)
        scores = np.zeros((len(docs),), dtype=np.float32)
        for i in range(len(docs)):
            tf = doc_tf[i] if i < len(doc_tf) else {}
            doc_len = sum(tf.values()) if tf else 1
            avgdl = sum(sum(d.values()) for d in doc_tf) / max(1, len(doc_tf))
            k1 = 1.5
            b = 0.75
            score_sum = 0.0
            for term in query_terms:
                freq = tf.get(term, 0)
                if freq <= 0:
                    continue
                numerator = freq * (k1 + 1)
                denominator = freq + k1 * (1 - b + b * (doc_len / avgdl))
                score_sum += idf.get(term, 0.0) * (numerator / denominator)
            scores[i] = float(score_sum)
        max_score = float(scores.max()) if scores.size else 0.0
        if max_score > 0:
            scores = scores / max_score
        return scores
    async def stats(self) -> Dict[str, Any]:
        async with self._lock:
            num_docs = len(self._docs)
            emb_shape = None if not self._emb_list else [len(self._emb_list), self._emb_list[0].shape[0]]
        return {"documents": num_docs, "embedding_matrix_shape": emb_shape}
    async def get_docs_by_urls(self, urls: List[str]) -> List[Document]:
        async with self._lock:
            output: List[Document] = []
            for url in urls:
                canonical_url = _canonicalize_url(url)
                idx = self._url_to_idx.get(canonical_url)
                if idx is not None and 0 <= idx < len(self._docs):
                    output.append(self._docs[idx])
        return output
class AnswerEngine:
    def __init__(self, index: VectorIndex) -> None:
        self._index = index
    async def answer(self, query: str, top_k: int, max_context_chars: int, use_openai_if_available: bool) -> Dict[str, Any]:
        search_response = await self._index.search(query, top_k=top_k, mode=SearchMode.HYBRID)
        results = search_response.get("results", [])
        retrieved_data = []
        for result in results:
            retrieved_data.append({"rank": result["rank"], "url": result["url"], "title": result["title"], "snippet": result["snippet"], "score": result["score"]})
        docs = await self._index.get_docs_by_urls([r["url"] for r in results])
        context, citations = await self._build_context(docs, max_context_chars=max_context_chars)
        api_key = os.getenv("OPENAI_API_KEY", "").strip()
        if use_openai_if_available and api_key:
            model = os.getenv("OPENAI_MODEL", "gpt-4o-mini").strip() or "gpt-4o-mini"
            try:
                answer_text = await self._openai_generate(api_key, model, query, context)
                return {"answer": answer_text, "retrieved": retrieved_data, "citations": citations, "provider": "openai"}
            except HTTPException:
                pass
        fallback_answer = self._extractive_answer(query, context)
        return {"answer": fallback_answer, "retrieved": retrieved_data, "citations": citations, "provider": "extractive"}
    async def _build_context(self, docs: List[Document], max_context_chars: int) -> Tuple[str, List[Dict[str, Any]]]:
        chunks: List[str] = []
        citations: List[Dict[str, Any]] = []
        remaining_chars = max_context_chars
        for doc in docs:
            if remaining_chars <= 0:
                break
            url = doc.url
            title = doc.title
            text = doc.text
            block = f"TITLE: {title}\nURL: {url}\nCONTENT: {text}\n"
            if len(block) > remaining_chars:
                available = remaining_chars - len(f"TITLE: {title}\nURL: {url}\nCONTENT: ")
                if available > 100:
                    text_truncated = text[:available]
                    block = f"TITLE: {title}\nURL: {url}\nCONTENT: {text_truncated}\n"
                else:
                    break
            chunks.append(block)
            citations.append({"url": url, "title": title})
            remaining_chars -= len(block)
        return "\n---\n".join(chunks), citations
    async def _openai_generate(self, api_key: str, model: str, query: str, context: str) -> str:
        endpoint = os.getenv("OPENAI_API_BASE", "").rstrip("/")
        url = f"{endpoint}/v1/chat/completions"
        system_message = "You are a retrieval-augmented assistant. Answer the user using only the provided context. If the context is insufficient, say so. Provide a concise answer and include inline citations as URLs."
        user_message = f"CONTEXT:\n{context}\n\nQUESTION:\n{query}\n\nANSWER:"
        headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
        body = {"model": model, "messages": [{"role": "system", "content": system_message}, {"role": "user", "content": user_message}], "temperature": 0.3}
        timeout_str = os.getenv("OPENAI_TIMEOUT_S", "45")
        try:
            timeout_s = max(5.0, min(120.0, float(timeout_str)))
        except ValueError:
            timeout_s = 45.0
        async with httpx.AsyncClient(http2=True) as client:
            try:
                response = await client.post(url, headers=headers, json=body, timeout=timeout_s)
            except httpx.RequestError as e:
                raise HTTPException(status_code=502, detail={"error": "LLM request failed", "reason": type(e).__name__})
            if response.status_code >= 400:
                raise HTTPException(status_code=502, detail={"error": "LLM request failed", "status": response.status_code})
            try:
                data = response.json()
            except Exception:
                raise HTTPException(status_code=502, detail={"error": "LLM response parse failed"})
        output_text = ""
        if isinstance(data, dict):
            if "choices" in data and isinstance(data["choices"], list) and len(data["choices"]) > 0:
                choice = data["choices"][0]
                if isinstance(choice, dict) and "message" in choice:
                    message = choice["message"]
                    if isinstance(message, dict) and "content" in message:
                        output_text = str(message["content"])
        return output_text.strip() or "No answer generated."
    def _extractive_answer(self, query: str, context: str) -> str:
        query_terms = set(_tokenize(query))
        text = _normalize_text(context)
        if not text:
            return "The index is empty or no relevant context was found."
        sentences = []
        current_sentence = []
        for char in text:
            current_sentence.append(char)
            if char in ".!?" and len(current_sentence) > 1:
                sentence_str = "".join(current_sentence).strip()
                if sentence_str:
                    sentences.append(sentence_str)
                current_sentence = []
        if current_sentence:
            sentence_str = "".join(current_sentence).strip()
            if sentence_str:
                sentences.append(sentence_str)
        scored_sentences: List[Tuple[float, str]] = []
        for sentence in sentences:
            clean_sentence = _normalize_text(sentence)
            if len(clean_sentence) < 20:
                continue
            tokens = _tokenize(clean_sentence)
            if not tokens:
                continue
            hits = sum(1 for token in tokens if token in query_terms)
            if hits <= 0:
                continue
            score = hits / max(1.0, float(len(set(tokens))))
            scored_sentences.append((score, clean_sentence))
        scored_sentences.sort(key=lambda item: item[0], reverse=True)
        picked_sentences: List[str] = []
        used_chars = 0
        max_chars = 1500
        for _, sentence in scored_sentences[:15]:
            if used_chars + len(sentence) + 1 > max_chars:
                break
            picked_sentences.append(sentence)
            used_chars += len(sentence) + 1
        if not picked_sentences:
            return (text[:max_chars] + ("..." if len(text) > max_chars else "")).strip()
        return " ".join(picked_sentences).strip()
